object WidgetHelper {
    private const val PREFS_NAME = "SynthesiscoWidgetPrefs"
    private const val KEY_OPACITY = "opacity_percent_"
    private const val KEY_GLASS_BLACK = "glass_black_"
    private const val KEY_TEXT_BLACK = "text_black_"
    private const val KEY_FONT_WEIGHT = "font_weight_"
    private const val KEY_CROP_Y = "crop_y_"
    private const val KEY_CROP_X = "crop_x_"
