    private fun getTodayKey(): Int {
        val cal = Calendar.getInstance()
        return cal.get(Calendar.YEAR) * 1000 + cal.get(Calendar.DAY_OF_YEAR)
    }

    fun saveConfig(
        context: Context,
        widgetId: Int,
        opacity: Int,
        isBlackGlass: Boolean,
        isBlackText: Boolean,
        fontWeight: Int,
        cropY: Int,
        cropX: Int,
        useBlur: Boolean,
        tapToReveal: Boolean
    ) {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val prevTapToReveal = isTapToRevealEnabled(context, widgetId)
        val editor = prefs.edit()
            .putInt(KEY_OPACITY + widgetId, opacity).putInt(KEY_OPACITY + "global", opacity)
            .putBoolean(KEY_GLASS_BLACK + widgetId, isBlackGlass).putBoolean(KEY_GLASS_BLACK + "global", isBlackGlass)
            .putBoolean(KEY_TEXT_BLACK + widgetId, isBlackText).putBoolean(KEY_TEXT_BLACK + "global", isBlackText)
            .putInt(KEY_FONT_WEIGHT + widgetId, fontWeight).putInt(KEY_FONT_WEIGHT + "global", fontWeight)
            .putInt(KEY_CROP_Y + widgetId, cropY).putInt(KEY_CROP_Y + "global", cropY)
            .putInt(KEY_CROP_X + widgetId, cropX).putInt(KEY_CROP_X + "global", cropX)
            .putBoolean(KEY_USE_BLUR + widgetId, useBlur).putBoolean(KEY_USE_BLUR + "global", useBlur)
            .putBoolean(KEY_TAP_TO_REVEAL + widgetId, tapToReveal).putBoolean(KEY_TAP_TO_REVEAL + "global", tapToReveal)

        // Si el usuario acaba de activar Tap to Reveal en los ajustes, lo dejamos listo para probar el toque
        if (tapToReveal && !prevTapToReveal) {
            editor.putInt(KEY_REVEALED_DAY + widgetId, -1)
            editor.putInt(KEY_REVEALED_DAY + "global", -1)
        }
        editor.apply()
    }

    fun isTapToRevealEnabled(context: Context, id: Int): Boolean {
        val p = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        return p.getBoolean(KEY_TAP_TO_REVEAL + id, p.getBoolean(KEY_TAP_TO_REVEAL + "global", true))
    }

    fun isPhraseRevealedToday(context: Context, id: Int): Boolean {
        if (!isTapToRevealEnabled(context, id)) return true
        val p = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val today = getTodayKey()
        val revealedForWidget = p.getInt(KEY_REVEALED_DAY + id, p.getInt(KEY_REVEALED_DAY + "global", -1))
        return revealedForWidget == today
    }

    fun markPhraseRevealedToday(context: Context, id: Int) {
        val p = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val today = getTodayKey()
        p.edit()
            .putInt(KEY_REVEALED_DAY + id, today)
            .putInt(KEY_REVEALED_DAY + "global", today)
            .apply()
    }

    fun resetDailyReveal(context: Context) {
        val p = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        p.edit().putInt(KEY_REVEALED_DAY + "global", -1).apply()
    }

