    fun saveCustomWallpaperFromUri(context: Context, uri: Uri): Boolean {
        return try {
            val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
            context.contentResolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it, null, bounds) }
            var sample = 1
            while (bounds.outWidth / sample > 1080 || bounds.outHeight / sample > 2200) sample *= 2
            val opts = BitmapFactory.Options().apply { inSampleSize = sample }
            val bmp = context.contentResolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it, null, opts) } ?: return false
            FileOutputStream(File(context.filesDir, WALLPAPER_FILE_NAME)).use { bmp.compress(Bitmap.CompressFormat.JPEG, 92, it) }
            true
        } catch (e: Exception) {
            false
        }
    }

    fun clearCustomWallpaper(context: Context) {
        try {
            val f = File(context.filesDir, WALLPAPER_FILE_NAME)
            if (f.exists()) f.delete()
        } catch (e: Exception) {}
    }

    fun loadRealWallpaperBitmap(context: Context): Bitmap? {
        try {
            val d = WallpaperManager.getInstance(context).drawable
            if (d is BitmapDrawable && d.bitmap != null) {
                return d.bitmap
            }
        } catch (e: Exception) {}

        try {
            val f = File(context.filesDir, WALLPAPER_FILE_NAME)
            if (f.exists()) {
                BitmapFactory.decodeFile(f.absolutePath)?.let { return it }
            }
        } catch (e: Exception) {}

        return null
    }

    private fun blurBitmap(source: Bitmap, radius: Int): Bitmap {
        if (radius <= 0) return source
        val scale = 0.20f
        val sw = max(24, (source.width * scale).roundToInt())
        val sh = max(24, (source.height * scale).roundToInt())
        val small = Bitmap.createScaledBitmap(source, sw, sh, true).copy(Bitmap.Config.ARGB_8888, true)
        val w = small.width
        val h = small.height
        val pix = IntArray(w * h)
        small.getPixels(pix, 0, w, 0, 0, w, h)
        val r = radius.coerceIn(1, 24)
        val temp = IntArray(w * h)

        for (pass in 0 until 3) {
            for (y in 0 until h) {
                var sr = 0; var sg = 0; var sb = 0; var cnt = 0
                val row = y * w
                for (x in -r..r) {
                    val c = pix[row + x.coerceIn(0, w - 1)]
                    sr += (c shr 16) and 0xFF; sg += (c shr 8) and 0xFF; sb += c and 0xFF; cnt++
                }
                for (x in 0 until w) {
                    temp[row + x] = (0xFF shl 24) or ((sr / cnt) shl 16) or ((sg / cnt) shl 8) or (sb / cnt)
                    val cOut = pix[row + (x - r).coerceIn(0, w - 1)]
                    val cIn = pix[row + (x + r + 1).coerceIn(0, w - 1)]
                    sr += ((cIn shr 16) and 0xFF) - ((cOut shr 16) and 0xFF)
                    sg += ((cIn shr 8) and 0xFF) - ((cOut shr 8) and 0xFF)
                    sb += (cIn and 0xFF) - (cOut and 0xFF)
                }
            }
            for (x in 0 until w) {
                var sr = 0; var sg = 0; var sb = 0; var cnt = 0
                for (y in -r..r) {
                    val c = temp[y.coerceIn(0, h - 1) * w + x]
                    sr += (c shr 16) and 0xFF; sg += (c shr 8) and 0xFF; sb += c and 0xFF; cnt++
                }
                for (y in 0 until h) {
                    pix[y * w + x] = (0xFF shl 24) or ((sr / cnt) shl 16) or ((sg / cnt) shl 8) or (sb / cnt)
                    val cOut = temp[(y - r).coerceIn(0, h - 1) * w + x]
                    val cIn = temp[(y + r + 1).coerceIn(0, h - 1) * w + x]
                    sr += ((cIn shr 16) and 0xFF) - ((cOut shr 16) and 0xFF)
                    sg += ((cIn shr 8) and 0xFF) - ((cOut shr 8) and 0xFF)
                    sb += (cIn and 0xFF) - (cOut and 0xFF)
                }
            }
        }
        small.setPixels(pix, 0, w, 0, 0, w, h)
        return Bitmap.createScaledBitmap(small, source.width, source.height, true)
    }

    fun getPhraseForToday(context: Context): String {
        return try {
            val jsonStr = context.assets.open("frases.json").bufferedReader().use { it.readText() }
            val array = JSONArray(jsonStr)
            val dayOfYear = Calendar.getInstance().get(Calendar.DAY_OF_YEAR) - 1
            array.getString(dayOfYear.coerceAtLeast(0) % array.length())
        } catch (e: Exception) {
            "That's when champions are made."
        }
    }

    fun getMidnightElapsedRealtimeBase(): Long {
        val now = System.currentTimeMillis()
        val midnight = Calendar.getInstance().apply {
            set(Calendar.HOUR_OF_DAY, 0); set(Calendar.MINUTE, 0); set(Calendar.SECOND, 0); set(Calendar.MILLISECOND, 0)
            add(Calendar.DAY_OF_YEAR, 1)
        }.timeInMillis
        return SystemClock.elapsedRealtime() + (midnight - now).coerceAtLeast(0L)
    }

    fun createFrostedGlassBitmap(
        context: Context,
        widthPx: Int,
        heightPx: Int,
        cornerRadiusPx: Float,
        opacityPercent: Int,
        isBlackGlass: Boolean,
        cropYPercent: Int,
        cropXPercent: Int,
        useBlur: Boolean,
        isSquareWidget: Boolean
    ): Bitmap {
        val w = widthPx.coerceIn(200, 1200)
        val h = heightPx.coerceIn(180, 1200)
        val bitmap = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        if (opacityPercent <= 0) return bitmap

        val canvas = Canvas(bitmap)
        val factor = (opacityPercent.coerceIn(0, 100) / 100f)
        val rect = RectF(2f, 2f, w - 2f, h - 2f)
        val clipPath = Path().apply { addRoundRect(rect, cornerRadiusPx, cornerRadiusPx, Path.Direction.CW) }

        canvas.save()
        canvas.clipPath(clipPath)

        val wp = if (useBlur) loadRealWallpaperBitmap(context) else null
        val hasBlurredBg = (wp != null)

        if (wp != null) {
            val widthRatio = if (isSquareWidget) 0.44f else 0.78f
            val cropW = (wp.width * widthRatio).roundToInt().coerceIn(40, wp.width)
            val cropH = ((cropW.toFloat() * h.toFloat()) / w.toFloat()).roundToInt().coerceIn(40, wp.height)

            val maxLeft = max(0, wp.width - cropW)
            val maxTop = max(0, wp.height - cropH)
            val left = (maxLeft * (cropXPercent.coerceIn(0, 100) / 100f)).roundToInt().coerceIn(0, maxLeft)
            val top = (maxTop * (cropYPercent.coerceIn(0, 100) / 100f)).roundToInt().coerceIn(0, maxTop)

            val cropped = Bitmap.createBitmap(wp, left, top, cropW, cropH)
            val scaled = Bitmap.createScaledBitmap(cropped, w, h, true)

            val blurRadius = max(2, (factor * 20f).roundToInt())
            val blurred = blurBitmap(scaled, blurRadius)

            val blurAlpha = (90 + 165 * factor).roundToInt().coerceIn(0, 255)
            val bgPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { alpha = blurAlpha }
            canvas.drawBitmap(blurred, 0f, 0f, bgPaint)
        }

        if (!isBlackGlass) {
            val maxAlpha = if (hasBlurredBg) 125f else 185f
            val aTop = (maxAlpha * factor).roundToInt().coerceIn(0, 255)
            val aMid = (maxAlpha * 0.78f * factor).roundToInt().coerceIn(0, 255)
            val aBot = (maxAlpha * 0.88f * factor).roundToInt().coerceIn(0, 255)

            val tintPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                shader = LinearGradient(
                    0f, 0f, w.toFloat(), h.toFloat(),
                    intArrayOf(
                        Color.argb(aTop, 220, 232, 242),
                        Color.argb(aMid, 175, 194, 210),
                        Color.argb(aBot, 148, 170, 188)
                    ),
                    floatArrayOf(0f, 0.5f, 1f),
                    Shader.TileMode.CLAMP
                )
            }
            canvas.drawRect(rect, tintPaint)

            val edgeGlowAlpha = (90 * factor).roundToInt().coerceIn(0, 255)
            val edgePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                style = Paint.Style.STROKE
                strokeWidth = max(12f, min(w, h) * 0.08f)
                color = Color.argb(edgeGlowAlpha, 240, 248, 255)
                maskFilter = BlurMaskFilter(max(10f, min(w, h) * 0.06f), BlurMaskFilter.Blur.NORMAL)
            }
            canvas.drawRoundRect(rect, cornerRadiusPx, cornerRadiusPx, edgePaint)
        } else {
            val maxAlpha = if (hasBlurredBg) 155f else 205f
            val aTop = (maxAlpha * factor).roundToInt().coerceIn(0, 255)
            val aMid = (maxAlpha * 0.86f * factor).roundToInt().coerceIn(0, 255)
            val aBot = (maxAlpha * 0.94f * factor).roundToInt().coerceIn(0, 255)

            val tintPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                shader = LinearGradient(
                    0f, 0f, w.toFloat(), h.toFloat(),
                    intArrayOf(
                        Color.argb(aTop, 26, 34, 44),
                        Color.argb(aMid, 14, 20, 28),
                        Color.argb(aBot, 8, 12, 18)
                    ),
                    floatArrayOf(0f, 0.5f, 1f),
                    Shader.TileMode.CLAMP
                )
            }
            canvas.drawRect(rect, tintPaint)

            val edgeGlowAlpha = (65 * factor).roundToInt().coerceIn(0, 255)
            val edgePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                style = Paint.Style.STROKE
                strokeWidth = max(12f, min(w, h) * 0.08f)
                color = Color.argb(edgeGlowAlpha, 160, 190, 220)
                maskFilter = BlurMaskFilter(max(10f, min(w, h) * 0.06f), BlurMaskFilter.Blur.NORMAL)
            }
            canvas.drawRoundRect(rect, cornerRadiusPx, cornerRadiusPx, edgePaint)
        }

        val sheenAlpha = ((if (isBlackGlass) 42 else 72) * factor).roundToInt().coerceIn(0, 255)
        val sheenPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            shader = LinearGradient(
                0f, 0f, w * 0.5f, h * 0.6f,
                intArrayOf(
                    Color.argb(sheenAlpha, 255, 255, 255),
                    Color.argb((sheenAlpha * 0.3f).toInt(), 255, 255, 255),
                    Color.argb(0, 255, 255, 255)
                ),
                floatArrayOf(0f, 0.5f, 1f),
                Shader.TileMode.CLAMP
            )
        }
        canvas.drawRect(rect, sheenPaint)

        val noisePaint = Paint()
        val rng = Random(77L)
        val noiseAlpha = (16 * factor).roundToInt().coerceIn(0, 255)
        if (noiseAlpha > 2) {
            val step = 3
            var y = 0
            while (y < h) {
                var x = 0
                while (x < w) {
                    noisePaint.color = if (rng.nextBoolean()) {
                        Color.argb(noiseAlpha, 255, 255, 255)
                    } else {
                        Color.argb((noiseAlpha * 0.6f).toInt(), 15, 25, 35)
                    }
                    canvas.drawPoint(x.toFloat(), y.toFloat(), noisePaint)
                    x += step
                }
                y += step
            }
        }

        canvas.restore()

        val borderWidth = max(1.8f, w * 0.0032f)
        val borderAlpha = (185 * min(1f, 0.35f + factor * 0.70f)).roundToInt().coerceIn(0, 255)
        val borderPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.STROKE
            strokeWidth = borderWidth
            color = Color.argb(borderAlpha, 255, 255, 255)
        }
        val bRect = RectF(borderWidth, borderWidth, w - borderWidth, h - borderWidth)
        canvas.drawRoundRect(bRect, cornerRadiusPx, cornerRadiusPx, borderPaint)

        return bitmap
    }

    private fun wrapWordsWhole(words: List<String>, paint: TextPaint, maxWidth: Float): List<String>? {
        val lines = mutableListOf<String>()
        var currentLine = ""
        for (word in words) {
            if (paint.measureText(word) > maxWidth) return null
            val test = if (currentLine.isEmpty()) word else "$currentLine $word"
            if (paint.measureText(test) <= maxWidth) {
                currentLine = test
            } else {
                if (currentLine.isNotEmpty()) lines.add(currentLine)
                currentLine = word
            }
        }
        if (currentLine.isNotEmpty()) lines.add(currentLine)
        return lines
    }

    fun createPhraseBitmap(phrase: String, widthPx: Int, heightPx: Int, weightLevel: Int, isBlackText: Boolean): Bitmap {
        val w = widthPx.coerceIn(220, 1400)
        val h = heightPx.coerceIn(140, 1000)
        val bitmap = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(bitmap)

        val words = phrase.trim().split(" ").filter { it.isNotEmpty() }
        if (words.isEmpty()) return bitmap

        val tf = when (weightLevel) {
            1 -> Typeface.create("sans-serif-medium", Typeface.NORMAL)
            2 -> Typeface.create("sans-serif", Typeface.BOLD)
            3 -> Typeface.create("sans-serif-black", Typeface.BOLD)
            else -> Typeface.create("sans-serif-black", Typeface.BOLD)
        }

        val strokeRatio = when (weightLevel) {
            1 -> 0f
            2 -> 0f
            3 -> 0.008f
            else -> 0.020f
        }

        val paint = TextPaint(Paint.ANTI_ALIAS_FLAG or Paint.SUBPIXEL_TEXT_FLAG).apply {
            typeface = tf
            isFakeBoldText = (weightLevel >= 3)
            letterSpacing = 0.01f
        }

        val usableWidth = w * 0.80f
        val usableHeight = h * 0.72f
        var bestSizePx = 20f
        var bestLines: List<String> = listOf(phrase)
        var testPx = min(w, h) * 0.21f

        while (testPx >= 12f) {
            paint.textSize = testPx
            val extra = testPx * strokeRatio
            val candidate = wrapWordsWhole(words, paint, usableWidth - extra * 2f)
            if (candidate != null && candidate.size * (testPx * 1.18f) <= usableHeight) {
                bestSizePx = testPx
                bestLines = candidate
                break
            }
            testPx -= 1f
        }

        val lineHeight = bestSizePx * 1.18f
        val totalBlockHeight = bestLines.size * lineHeight
        val fm = paint.apply { textSize = bestSizePx }.fontMetrics
        val firstBaselineY = (h - totalBlockHeight) / 2f - fm.ascent * 0.88f

        val drawPaint = TextPaint(paint).apply {
            textSize = bestSizePx
            style = if (strokeRatio > 0f) Paint.Style.FILL_AND_STROKE else Paint.Style.FILL
            strokeWidth = bestSizePx * strokeRatio
            strokeJoin = Paint.Join.ROUND
            strokeCap = Paint.Cap.ROUND
            color = if (isBlackText) Color.rgb(15, 23, 30) else Color.WHITE
            val shadowCol = if (isBlackText) Color.argb(90, 255, 255, 255) else Color.argb(130, 0, 0, 0)
            setShadowLayer(bestSizePx * 0.14f, 0f, bestSizePx * 0.05f, shadowCol)
        }

        for ((idx, line) in bestLines.withIndex()) {
            val lw = drawPaint.measureText(line)
            canvas.drawText(line, (w - lw) / 2f, firstBaselineY + idx * lineHeight, drawPaint)
        }
        return bitmap
    }

    fun updateSingleWidget(context: Context, appWidgetManager: AppWidgetManager, widgetId: Int) {
        val views = RemoteViews(context.packageName, R.layout.widget_layout)
        val options: Bundle? = try { appWidgetManager.getAppWidgetOptions(widgetId) } catch (e: Exception) { null }
        val info = try { appWidgetManager.getAppWidgetInfo(widgetId) } catch (e: Exception) { null }
        val isSquare = info?.provider?.className?.contains("SquarePhraseWidget") == true

        val minW = options?.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH, 0)?.takeIf { it > 40 } ?: if (isSquare) 145 else 290
        val minH = options?.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT, 0)?.takeIf { it > 40 } ?: 145

        val density = context.resources.displayMetrics.density.coerceIn(1.5f, 3.5f)
        val cw = (minW * density).toInt().coerceIn(260, 1200)
        val ch = (minH * density).toInt().coerceIn(220, 900)

        val configuredOpacity = getOpacity(context, widgetId)
        val blackGlass = isBlackGlass(context, widgetId)
        val blackText = isBlackText(context, widgetId)
        val weight = getFontWeight(context, widgetId)
        val cropY = getCropY(context, widgetId)
        val cropX = getCropX(context, widgetId)
        val useBlur = useWallpaperBlur(context, widgetId)

        val isRevealed = isPhraseRevealedToday(context, widgetId)

        // Si aún no se ha revelado hoy, se muestra menos transparente (más esmerilado/opaco) y con el texto "Tap to reveal"
        val effectiveOpacity = if (isRevealed) {
            configuredOpacity
        } else {
            max(82, min(98, configuredOpacity + 30))
        }

        val displayedText = if (isRevealed) {
            getPhraseForToday(context)
        } else {
            "Tap to reveal"
        }

        val glassBmp = createFrostedGlassBitmap(context, cw, ch, 20f * density, effectiveOpacity, blackGlass, cropY, cropX, useBlur, isSquare)
        val phraseBmp = createPhraseBitmap(displayedText, (cw - 20f * density).toInt(), (ch - 36f * density).toInt(), weight, blackText)

        views.setImageViewBitmap(R.id.widget_bg_image, glassBmp)
        views.setImageViewBitmap(R.id.widget_phrase_image, phraseBmp)
        views.setTextColor(R.id.widget_countdown, if (blackText) Color.argb(210, 15, 23, 30) else Color.argb(215, 255, 255, 255))

        views.setChronometerCountDown(R.id.widget_countdown, true)
        views.setChronometer(R.id.widget_countdown, getMidnightElapsedRealtimeBase(), null, true)

        if (!isRevealed) {
            // Al tocar el widget bloqueado, revela la frase del día inmediatamente
            val revealClass = if (isSquare) SquarePhraseWidget::class.java else RectanglePhraseWidget::class.java
            val revealIntent = Intent(context, revealClass).apply {
                action = "com.synthesisco.frases.ACTION_REVEAL_PHRASE"
                putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID, widgetId)
            }
            val pi = PendingIntent.getBroadcast(
                context,
                widgetId + 5000,
                revealIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            views.setOnClickPendingIntent(R.id.widget_root, pi)
        } else {
            // Una vez revelada la frase, tocar el widget abre los ajustes normalmente
            val cfgIntent = Intent(context, WidgetConfigActivity::class.java).apply {
                putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID, widgetId)
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP
            }
            val pi = PendingIntent.getActivity(
                context,
                widgetId,
                cfgIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            views.setOnClickPendingIntent(R.id.widget_root, pi)
        }

        appWidgetManager.updateAppWidget(widgetId, views)
    }

    fun updateAllWidgets(context: Context) {
        val m = AppWidgetManager.getInstance(context)
        for (id in m.getAppWidgetIds(ComponentName(context, SquarePhraseWidget::class.java))) updateSingleWidget(context, m, id)
        for (id in m.getAppWidgetIds(ComponentName(context, RectanglePhraseWidget::class.java))) updateSingleWidget(context, m, id)
    }

    fun scheduleMidnightUpdate(context: Context) {
        val am = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
        val i = Intent(context, SquarePhraseWidget::class.java).apply { action = "com.synthesisco.frases.ACTION_MIDNIGHT_UPDATE" }
        val pi = PendingIntent.getBroadcast(context, 999, i, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)
        val mid = Calendar.getInstance().apply {
            set(Calendar.HOUR_OF_DAY, 0); set(Calendar.MINUTE, 0); set(Calendar.SECOND, 1); set(Calendar.MILLISECOND, 0)
            add(Calendar.DAY_OF_YEAR, 1)
        }
        am.setInexactRepeating(AlarmManager.RTC, mid.timeInMillis, AlarmManager.INTERVAL_DAY, pi)
    }
}

package com.synthesisco.frases

import android.appwidget.AppWidgetManager
import android.appwidget.AppWidgetProvider
import android.content.Context
import android.content.Intent
import android.os.Bundle

class SquarePhraseWidget : AppWidgetProvider() {
    override fun onUpdate(context: Context, appWidgetManager: AppWidgetManager, appWidgetIds: IntArray) {
        for (id in appWidgetIds) {
            WidgetHelper.updateSingleWidget(context, appWidgetManager, id)
        }
        WidgetHelper.scheduleMidnightUpdate(context)
    }

    override fun onAppWidgetOptionsChanged(
        context: Context,
        appWidgetManager: AppWidgetManager,
        appWidgetId: Int,
        newOptions: Bundle
    ) {
        super.onAppWidgetOptionsChanged(context, appWidgetManager, appWidgetId, newOptions)
        WidgetHelper.updateSingleWidget(context, appWidgetManager, appWidgetId)
    }

    override fun onReceive(context: Context, intent: Intent) {
        super.onReceive(context, intent)
        when (intent.action) {
            "com.synthesisco.frases.ACTION_MIDNIGHT_UPDATE" -> {
                WidgetHelper.resetDailyReveal(context)
                WidgetHelper.updateAllWidgets(context)
            }
            "com.synthesisco.frases.ACTION_REVEAL_PHRASE" -> {
                val id = intent.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID, AppWidgetManager.INVALID_APPWIDGET_ID)
                WidgetHelper.markPhraseRevealedToday(context, id)
                WidgetHelper.updateAllWidgets(context)
            }
        }
    }
}

